const products=[['Broccoli','Vegetables',120,'🥦','1 kg'],['Strawberries','Fruits',180,'🍓','250 g'],['Carrots','Vegetables',60,'🥕','1 kg'],['Bananas','Fruits',50,'🍌','6 pieces'],['Tomatoes','Vegetables',45,'🍅','1 kg'],['Apples','Fruits',160,'🍎','1 kg'],['Sweet corn','Vegetables',80,'🌽','2 pieces'],['Avocado','Fruits',140,'🥑','1 piece'],['Grapes','Fruits',90,'🍇','500 g'],['Potatoes','Vegetables',35,'🥔','1 kg'],['Almonds','Nuts',240,'🌰','250 g'],['Cucumber','Vegetables',40,'🥒','500 g']].map((p,id)=>({id,name:p[0],category:p[1],price:p[2],emoji:p[3],unit:p[4]}));
let cart={};try{const saved=JSON.parse(localStorage.getItem('greenkart-cart')||'{}');for(const p of products)if(Number.isInteger(saved[p.id])&&saved[p.id]>0&&saved[p.id]<=99)cart[p.id]=saved[p.id]}catch{}let category='All products',search='',sort='featured',promo=false;const quantities={};const app=document.querySelector('#app');const money=n=>'₹'+n.toFixed(2).replace('.00','');const subtotal=()=>products.reduce((sum,p)=>sum+p.price*(cart[p.id]||0),0);const count=()=>Object.values(cart).reduce((a,b)=>a+b,0);const total=()=>Math.round(subtotal()*(promo?.9:1)*100)/100;
function persist(){localStorage.setItem('greenkart-cart',JSON.stringify(cart));document.querySelector('#badge').textContent=count();document.querySelector('#headerTotal').textContent=money(total())}function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',2200)}
function stepper(p,q,context){
 const errorId=`quantity-error-${context}-${p.id}`;
 return `<div><div class="stepper"><button type="button" aria-label="Decrease ${p.name}" data-step="-1" data-id="${p.id}" data-context="${context}" ${q<=1?'disabled':''}>−</button><input aria-label="${p.name} quantity" aria-describedby="${errorId}" type="number" min="1" max="99" step="1" value="${q}" data-qty="${p.id}" data-context="${context}"><button type="button" aria-label="Increase ${p.name}" data-step="1" data-id="${p.id}" data-context="${context}" ${q>=99?'disabled':''}>+</button></div><p id="${errorId}" class="error" role="status" hidden></p></div>`;
}
function updateQuantity(id,context,value){
 const target=context==='cart'?cart:quantities;
 const input=document.querySelector(`[data-qty="${id}"][data-context="${context}"]`);
 const error=document.querySelector(`#quantity-error-${context}-${id}`);
 const quantity=Number(value);
 if(!Number.isInteger(quantity)||quantity<1||quantity>99){
  input.value=target[id]||1;
  input.setAttribute('aria-invalid','true');
  error.textContent='Enter a whole-number quantity from 1 to 99. The previous quantity has been kept.';
  error.hidden=false;
  return;
 }
 target[id]=quantity;
 if(context==='cart'){
  persist();bag();
  document.querySelector(`[data-qty="${id}"][data-context="cart"]`).focus();
 }else{
  input.value=quantity;
  input.removeAttribute('aria-invalid');
  error.hidden=true;
  error.textContent='';
  for(const step of [-1,1])document.querySelector(`[data-step="${step}"][data-id="${id}"][data-context="shop"]`).disabled=step===-1?quantity===1:quantity===99;
 }
}
function shop(){app.innerHTML=`<section class="hero"><div><p class="eyebrow">FROM THE GARDEN TO YOUR BAG</p><h1>Good food.<br>Fresh beginnings.</h1><p>Your everyday essentials, picked with care.<br>Fill your basket with a little goodness.</p></div><div class="hero-art" aria-hidden="true">🥬 🥑 🥕</div><span class="hero-tag">Fresh picks. Simple pleasures.</span></section><div class="benefits"><span>Freshly picked produce</span><span>Thoughtfully priced</span><span>Made for everyday goodness</span></div><section><div class="shop-head"><div><p class="eyebrow">THE FRESH COLLECTION</p><h2>A basket full of good things</h2><div class="sub">Seasonal favorites and everyday essentials.</div></div><input data-testid="product-search" class="search" id="search" type="search" placeholder="⌕  Search fresh groceries" aria-label="Search products"></div><div class="toolbar"><div class="filters">${['All products','Vegetables','Fruits','Nuts'].map(c=>`<button data-filter="${c}" class="${category===c?'active':''}">${c}</button>`).join('')}</div><select id="sort" aria-label="Sort products"><option value="featured">Sort: Featured</option><option value="low">Price: Low to high</option><option value="high">Price: High to low</option><option value="name">Name: A to Z</option></select></div><p class="sub" id="results"></p><div class="grid" id="grid"></div></section>`;document.querySelector('#search').value=search;document.querySelector('#sort').value=sort;renderProducts();document.querySelector('#search').oninput=e=>{search=e.target.value;renderProducts()};document.querySelector('#sort').onchange=e=>{sort=e.target.value;renderProducts()}}
function renderProducts(){let list=products.filter(p=>(category==='All products'||p.category===category)&&p.name.toLowerCase().includes(search.trim().toLowerCase()));if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));document.querySelector('#results').textContent=`${list.length} products · Fresh finds for your day`;document.querySelector('#grid').innerHTML=list.map(p=>`<article class="product" data-testid="product-${p.id}"><div class="visual"><span class="tag">${p.category==='Vegetables'?'FARM FRESH':p.category==='Fruits'?'FRESH PICK':'PANTRY PICK'}</span><span role="img" aria-label="${p.name}">${p.emoji}</span></div><div class="product-body"><span class="category">${p.category}</span><h3>${p.name}</h3><span class="unit">${p.unit}</span><div class="price-line"><span class="price">${money(p.price)}</span>${stepper(p,quantities[p.id]||1,'shop')}</div><button class="add" data-add="${p.id}">＋ Add to bag</button></div></article>`).join('')||'<div class="empty">No products found. Try another search or category.</div>'}
function summary(checkout=false){return `<aside class="panel"><h2>Order summary</h2><div class="total-line"><span>Items (${count()})</span><span>${money(subtotal())}</span></div><div class="total-line"><span>Discount ${promo?'(10%)':''}</span><span>−${money(subtotal()-total())}</span></div><div class="total-line"><span>Delivery</span><span>Free</span></div><div class="total-line strong"><span>Total</span><span data-testid="order-total">${money(total())}</span></div>${!checkout?`<form id="promo" class="promo"><input aria-label="Promo code" placeholder="Enter promo code" ${promo?'disabled value="FRESH10"':''}><button ${promo?'disabled':''}>${promo?'Applied':'Apply'}</button></form><p id="promoMessage" role="status" class="hint">${promo?'FRESH10 applied. You saved 10%.':'A little treat: use FRESH10 for 10% off.'}</p><button class="primary" id="checkout" data-testid="checkout">Proceed to checkout →</button>`:''}<p class="hint">Practice order only. No real payment or delivery.</p></aside>`}
function bag(){app.innerHTML=`<button class="back" data-shop>← Continue shopping</button><div class="page-title"><p class="eyebrow">YOUR FRESH FINDS</p><h1>Your shopping bag</h1><p class="sub">${count()} items, a whole lot of goodness.</p></div>${!count()?'<div class="panel empty"><h2>Your bag is waiting for something fresh.</h2><button class="primary" data-shop>Explore groceries</button></div>':`<div class="checkout-grid"><section class="panel">${products.filter(p=>cart[p.id]).map(p=>`<div class="cart-row" data-testid="cart-item-${p.id}"><span class="emoji">${p.emoji}</span><div class="details"><h3>${p.name}</h3><span class="unit">${p.unit} · ${money(p.price)} each</span></div>${stepper(p,cart[p.id],'cart')}<strong>${money(p.price*cart[p.id])}</strong><button class="remove" data-remove="${p.id}" aria-label="Remove ${p.name}">Remove</button></div>`).join('')}</section>${summary()}</div>`}`;if(count()){document.querySelector('#checkout').onclick=()=>location.hash='/checkout';document.querySelector('#promo').onsubmit=e=>{e.preventDefault();const code=e.target.querySelector('input').value.trim().toUpperCase();if(code==='FRESH10'){promo=true;persist();bag()}else{document.querySelector('#promoMessage').className='error';document.querySelector('#promoMessage').textContent=code?'Invalid promo code. Please try again.':'Enter a promo code.'}}}}
function checkout(){if(!count()){location.hash='/cart';return}app.innerHTML=`<button class="back" id="backBag">← Back to bag</button><div class="page-title"><p class="eyebrow">ONE LAST STEP</p><h1>Finish your fresh start.</h1><p class="sub">Choose a destination to complete your practice order.</p></div><div class="checkout-grid"><form class="panel" id="order"><h2>Delivery destination</h2><label class="form-label" for="country">Country</label><select class="country" id="country" required data-testid="country"><option value="">Select a country</option>${['Australia','Canada','France','Germany','India','Japan','Singapore','United Arab Emirates','United Kingdom','United States'].map(c=>`<option>${c}</option>`).join('')}</select><label class="check"><input type="checkbox" required data-testid="terms"> I agree to the demo terms and understand that this is a simulated order.</label><button class="primary" data-testid="place-order">Place demo order →</button></form>${summary(true)}</div>`;document.querySelector('#backBag').onclick=()=>location.hash='/cart';document.querySelector('#order').onsubmit=e=>{e.preventDefault();const destination=document.querySelector('#country').value;const paid=total();cart={};promo=false;persist();history.replaceState(null,'','#/confirmation');app.innerHTML=`<section class="panel confirmation" data-testid="order-confirmation"><div class="checkmark">✓</div><p class="eyebrow">GOODNESS IS ON THE WAY</p><h1>Thank you for your order!</h1><p>Your demo order for ${destination} is confirmed.</p><h2>${money(paid)}</h2><p class="hint">This was a practice checkout. No payment was taken and no goods will be delivered.</p><button class="primary" data-shop>Back to fresh finds →</button></section>`}}
function route(){const path=location.hash.slice(1);if(path==='/cart')bag();else if(path==='/checkout')checkout();else shop();window.scrollTo(0,0)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-shop'))location.hash='/';if(b.dataset.filter){category=b.dataset.filter;shop()}if(b.dataset.add!==undefined){const id=+b.dataset.add;cart[id]=Math.min(99,(cart[id]||0)+(quantities[id]||1));persist();toast(products[id].name+' added to your bag')}if(b.dataset.remove!==undefined){delete cart[b.dataset.remove];if(!count())promo=false;persist();bag()}if(b.dataset.step){const id=+b.dataset.id,context=b.dataset.context;const target=context==='cart'?cart:quantities;updateQuantity(id,context,(target[id]||1)+Number(b.dataset.step))}});

document.addEventListener('change',event=>{
 if(event.target.dataset.qty!==undefined)updateQuantity(Number(event.target.dataset.qty),event.target.dataset.context,event.target.value);
});document.querySelector('#cartButton').onclick=()=>location.hash='/cart';document.querySelector('#about').onclick=()=>document.querySelector('#info').showModal();document.querySelector('.close').onclick=()=>document.querySelector('#info').close();window.addEventListener('hashchange',route);persist();route();
